    outage_refund(p, Decimal("1000.01"), T0)
except BillingError as e:
    print("above:", e.code)
# above with approver
p = mk(); outage_refund(p, Decimal("1000.01"), T0, approved_by="mgr"); print("approved ok", p.refunded_amount)
